import sys, json
import pandas as pd
import numpy as np

def to_float(x):
    return float(np.round(x, 2))

def pct(x):
    return float(np.round(x, 1))

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # Totals
    tot_rev_tw = df['Revenue_TW'].sum(skipna=True)
    tot_rev_lw = df['Revenue_LW'].sum(skipna=True)
    tot_rev_ly = df['Revenue_LY'].sum(skipna=True) if df['Revenue_LY'].notna().any() else None
    tot_units_tw = df['Units_TW'].sum(skipna=True)
    tot_orders_tw = df['Orders_TW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": to_float(tot_rev_tw),
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": to_float(tot_rev_lw),
        "formula": "sum(Revenue_LW)"
    })

    if tot_rev_lw and not np.isnan(tot_rev_lw) and tot_rev_lw != 0:
        wow_total = (tot_rev_tw - tot_rev_lw) / tot_rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": pct(wow_total),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if tot_rev_ly is not None and not np.isnan(tot_rev_ly) and tot_rev_ly != 0:
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "LY",
            "value": to_float(tot_rev_ly),
            "formula": "sum(Revenue_LY)"
        })
        yoy_total = (tot_rev_tw - tot_rev_ly) / tot_rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": pct(yoy_total),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    if not np.isnan(tot_units_tw):
        facts.append({
            "entity": "TOTAL", "metric": "units", "period": "TW",
            "value": to_float(tot_units_tw),
            "formula": "sum(Units_TW)"
        })

    if not np.isnan(tot_orders_tw):
        facts.append({
            "entity": "TOTAL", "metric": "orders", "period": "TW",
            "value": to_float(tot_orders_tw),
            "formula": "sum(Orders_TW)"
        })

    # Sort entities by rank for priority
    df_sorted = df.sort_values('Rank', na_position='last')

    for _, row in df_sorted.iterrows():
        entity = row['Entity']

        if pd.notna(row.get('Revenue_TW')):
            facts.append({
                "entity": entity, "metric": "revenue", "period": "TW",
                "value": to_float(row['Revenue_TW']),
                "formula": "Revenue_TW"
            })

        if pd.notna(row.get('Share_Pct')):
            facts.append({
                "entity": entity, "metric": "share", "period": "TW",
                "value": pct(row['Share_Pct']),
                "formula": "Share_Pct"
            })

        if pd.notna(row.get('Rank')):
            facts.append({
                "entity": entity, "metric": "rank", "period": "TW",
                "value": to_float(row['Rank']),
                "formula": "Rank"
            })

        if pd.notna(row.get('WoW_Pct')):
            facts.append({
                "entity": entity, "metric": "revenue", "period": "WoW",
                "value": pct(row['WoW_Pct']),
                "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
            })

        if pd.notna(row.get('YoY_Pct')):
            facts.append({
                "entity": entity, "metric": "revenue", "period": "YoY",
                "value": pct(row['YoY_Pct']),
                "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
            })

    # Biggest WoW mover
    wow_valid = df.dropna(subset=['WoW_Pct'])
    if not wow_valid.empty:
        idx_max = wow_valid['WoW_Pct'].idxmax()
        idx_min = wow_valid['WoW_Pct'].idxmin()
        facts.append({
            "entity": df.loc[idx_max, 'Entity'], "metric": "revenue", "period": "WoW",
            "value": pct(df.loc[idx_max, 'WoW_Pct']),
            "formula": "max WoW_Pct among entities"
        })
        if idx_min != idx_max:
            facts.append({
                "entity": df.loc[idx_min, 'Entity'], "metric": "revenue", "period": "WoW",
                "value": pct(df.loc[idx_min, 'WoW_Pct']),
                "formula": "min WoW_Pct among entities"
            })

    # Biggest YoY mover
    yoy_valid = df.dropna(subset=['YoY_Pct'])
    if not yoy_valid.empty:
        idx_max = yoy_valid['YoY_Pct'].idxmax()
        idx_min = yoy_valid['YoY_Pct'].idxmin()
        facts.append({
            "entity": df.loc[idx_max, 'Entity'], "metric": "revenue", "period": "YoY",
            "value": pct(df.loc[idx_max, 'YoY_Pct']),
            "formula": "max YoY_Pct among entities"
        })
        if idx_min != idx_max:
            facts.append({
                "entity": df.loc[idx_min, 'Entity'], "metric": "revenue", "period": "YoY",
                "value": pct(df.loc[idx_min, 'YoY_Pct']),
                "formula": "min YoY_Pct among entities"
            })

    # Dedup (keep first occurrence)
    seen = set()
    unique_facts = []
    for f in facts:
        key = (f['entity'], f['metric'], f['period'])
        if key not in seen:
            seen.add(key)
            unique_facts.append(f)

    # Limit to 25
    unique_facts = unique_facts[:25]

    print(json.dumps(unique_facts))

if __name__ == "__main__":
    main()
